import{I as e,J as t,M as n,_ as r,g as i,h as a,p as o,t as s,u as c}from"./plugin-vue_export-helper-Dy_UwxR5.js";var l=JSON.parse(`{"path":"/forge/dimension/4.%E4%B8%89%E9%98%B6%E6%AE%B5%E4%B8%8E%E6%97%A0%E5%B0%BD%E6%8C%91%E6%88%98.html","title":"三阶段 | 原版文档","lang":"zh-CN","frontmatter":{"title":"三阶段","createTime":"2026/3/29","author":"波乱霜华 | 对了好久"},"git":{},"filePathRelative":"forge/dimension/4.三阶段与无尽挑战.md","headers":[]}`),u={name:`4.三阶段与无尽挑战.md`};function d(s,l,u,d,f,p){let m=e(`VPLink`);return n(),o(`div`,null,[l[7]||=a(`<p>杀穿整合包让流派登峰造极</p><p class="read-more">本阶段：生物在一二阶段血量膨胀的基础上全体再增加至<mark>10倍血量</mark>，<mark>5倍护甲</mark>，<mark>1.5倍攻击力</mark>，同时<mark class="note">增加140%护甲穿透</mark>，护甲韧性抵消穿透的比率不变。</p><p><strong>现在末影龙每次死亡默认掉落1个龙蛋</strong></p><h2 id="介绍" tabindex="-1"><a class="header-anchor" href="#介绍"><span>介绍</span></a></h2><p>三阶段将会开放末地和二轮世界，探索unusual end模组提供的群系和二轮世界并强化锻造锤与锻造工具挑战三阶段的BOSS，获取最强材料！</p><p>三阶段任务中会出现一个特殊事件——<mark>灾厄旗帜袭击</mark>，与末地任务线互相牵制，完成这一事件才能挑战末地任务线最终BOSS——末地守卫。</p><h2 id="解锁项目" tabindex="-1"><a class="header-anchor" href="#解锁项目"><span>解锁项目</span></a></h2><p>可探索维度</p><ul><li>一二阶段所有维度</li><li>末地</li><li>二轮世界</li></ul><p>Alex洞穴出现地点</p><ul><li>渊海陷窟/原始洞穴→二轮世界</li></ul><p>Tetra饰品</p>`,12),c(`ul`,null,[l[3]||=c(`li`,null,`护心镜`,-1),c(`li`,null,[l[1]||=i(`荣耀之证 卷轴：见`,-1),r(m,{href:`../scrolls/%E5%8D%B7%E8%BD%B43.md`},{default:t(()=>[...l[0]||=[i(`卷轴`,-1)]]),_:1}),l[2]||=i(`页面`,-1)])]),c(`p`,null,[l[5]||=i(`模板和盔甲纹饰：见`,-1),r(m,{href:`../%E9%94%BB%E9%80%A0%E6%A8%A1%E6%9D%BF.md`},{default:t(()=>[...l[4]||=[i(`锻造模板`,-1)]]),_:1}),l[6]||=i(`页面`,-1)]),l[8]||=a(`<p>可用工具等级：锤9级 切削7级 斧9级</p><h2 id="三阶段会出现的boss" tabindex="-1"><a class="header-anchor" href="#三阶段会出现的boss"><span>三阶段会出现的BOSS</span></a></h2><table><thead><tr><th style="text-align:center;">原版BOSS</th><th style="text-align:center;">小BOSS</th><th style="text-align:center;">大BOSS</th><th style="text-align:center;">关底BOSS</th><th style="text-align:center;">支线额外BOSS</th></tr></thead><tbody><tr><td style="text-align:center;">末影龙</td><td style="text-align:center;">末地石傀儡<br>潜影拟态者<br>昼从者/夜伏者<br>末地遣使<br>繁兴使者<br>沉降领主</td><td style="text-align:center;">紫沙鬼婆<br>蚀龙兽<br>蛇龙执战者<br>明路巨兽<br>碎船兽<br>暝煌龙<br>镇山大王</td><td style="text-align:center;">末影守卫</td><td style="text-align:center;">无</td></tr></tbody></table><h2 id="进入四阶段" tabindex="-1"><a class="header-anchor" href="#进入四阶段"><span>进入四阶段</span></a></h2><p>完成末地、二轮世界两条任务路线 <img src="/assets/image5-DArzTvSO.png" alt="任务展示" loading="lazy"><img src="/assets/image6-D6ckCytz.png" alt="任务展示" loading="lazy"></p><h2 id="四阶段-结束了" tabindex="-1"><a class="header-anchor" href="#四阶段-结束了"><span>四阶段（结束了？）</span></a></h2><p>普遍认为三阶段结束后整合包已经通关，但那些追求更多更刺激的战斗的人呢？</p><p>四阶段为追求极限的玩家准备了一个特殊的竞技场维度，玩家可以在其中开启无尽挑战</p><p><strong>无尽挑战机制</strong></p><ol><li>四阶段的任务奖励会给玩家特殊道具<code>绯红钥匙</code>，手持潜行使用后将传送到四阶段维度，加载片刻后竞技场浮岛将会出现，右击中心的召唤祭坛可以开启无尽挑战。</li><li>关卡难度会越来越高且波次无上限但打通50波可视为通关，奖励为三个通用饰品栏位。</li><li>每五波为精英怪波次，通关获得钻石奖牌，手持右键可跳过三波次；每十波为BOSS波次，通关可获得下界合金奖牌，手持右键可跳过五波次。</li></ol><div class="hint-container tip"><p class="hint-container-title">来自笔者的一句忠告</p><p>小心大舌头舐脑魔，小心不要压血压太狠,小心蚀龙兽对你设备的卡顿攻击。</p></div><hr><p>至此本整合包的所有流程算是结束了，但一路走来也没有人能玩遍所有流派。所以在此我建议多周目游玩以获得更多游戏体验，或者加入官方讨论群和频道，学习他人的锻造心得，提升自己的眼界。</p>`,13)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};